+// --- Component: Passengers ---
+
+type WaitingPassenger = { id: number; stationId: string; destination: StationShape };
+
+const PASSENGER_EVERY_MS = 2000;
+const SHAPES: StationShape[] = ["circle", "triangle", "square"];
+
+function randomPassenger(id: number): WaitingPassenger {
+  const station = STATIONS[Math.floor(Math.random() * STATIONS.length)];
+  const options = SHAPES.filter((shape) => shape !== station.shape);
+  return { id, stationId: station.id, destination: options[Math.floor(Math.random() * options.length)] };
+}
+
+function PassengerDot({ x, y, shape }: { x: number; y: number; shape: StationShape }) {
+  if (shape === "circle") return <Circle cx={x + 3} cy={y + 3} r={3} fill="#374151" pointerEvents="none" />;
+  if (shape === "square") return <Rect x={x} y={y} width={6} height={6} fill="#374151" pointerEvents="none" />;
+  return <Polygon points={`${x + 3},${y} ${x},${y + 6} ${x + 6},${y + 6}`} fill="#374151" pointerEvents="none" />;
+}
